// The example's TEST-ONLY keys must be the fixture keys (both generated by tools/gen_test_vectors.py), and the example
// key table must accept the fixture signatures: nothing in the repo may drift apart.
#include <unity.h>
#include <cstring>
#include "../../examples/minimal/src/test_only_keys.h"
#include "fota_signature.h"
#include "fota_test_vectors.h"
#include "host/fota_openssl.h"

using namespace fota;

void setUp() {}
void tearDown() {}

static void test_example_keys_are_the_fixture_keys() {
    TEST_ASSERT_EQUAL_STRING(TEST_ONLY_KEY_A_PEM, kExampleTestOnlyOpenBaoPem);
    TEST_ASSERT_EQUAL_STRING(TEST_ONLY_KEY_B_PEM, kExampleTestOnlyBreakGlassPem);
}

static void test_example_key_ids_are_test_only() {
    TEST_ASSERT_EQUAL_STRING("test-only-esp-fleet-ota", kExampleTestOnlyOpenBaoKeyId);
    TEST_ASSERT_EQUAL_STRING("test-only-esp-fleet-ota-breakglass", kExampleTestOnlyBreakGlassKeyId);
}

static void test_example_table_verifies_fixture_signatures() {
    const TrustedKey keys[] = {
        {kExampleTestOnlyOpenBaoKeyId, 1, (const uint8_t*)kExampleTestOnlyOpenBaoPem, strlen(kExampleTestOnlyOpenBaoPem)},
        {kExampleTestOnlyBreakGlassKeyId, 0, (const uint8_t*)kExampleTestOnlyBreakGlassPem,
         strlen(kExampleTestOnlyBreakGlassPem)},
    };
    OpensslSha256 sha;
    OpensslEcdsaP256 ecdsa;
    const size_t n = strlen(TEST_ONLY_MANIFEST);
    TEST_ASSERT_EQUAL_STRING("Ok", sigErrorName(verifyManifestSignature(TEST_ONLY_MANIFEST, n, kExampleTestOnlyOpenBaoKeyId,
        TEST_ONLY_SIG_A_VAULT_V1, strlen(TEST_ONLY_SIG_A_VAULT_V1), keys, 2, sha, ecdsa)));
    TEST_ASSERT_EQUAL_STRING("Ok", sigErrorName(verifyManifestSignature(TEST_ONLY_MANIFEST, n, kExampleTestOnlyBreakGlassKeyId,
        TEST_ONLY_SIG_B_B64, strlen(TEST_ONLY_SIG_B_B64), keys, 2, sha, ecdsa)));
}

int main(int, char**) {
    UNITY_BEGIN();
    RUN_TEST(test_example_keys_are_the_fixture_keys);
    RUN_TEST(test_example_key_ids_are_test_only);
    RUN_TEST(test_example_table_verifies_fixture_signatures);
    return UNITY_END();
}
